  for (const [code, t] of Object.entries(D.tpl)) if (TEMPLATE[code]) {
    Object.assign(TEMPLATE[code], { name: t.name, goal: t.goal, warmNote: t.warmNote });
    TEMPLATE[code].items.forEach((it, i) => { if (t.slots[i]) it.slot = t.slots[i]; });
  }
  MEALS.forEach((m, i) => { if (D.meals[i]) Object.assign(m, D.meals[i]); });
  Object.assign(MEAL_MOMENTS, D.moments);
  QUICK_FOODS.forEach((q, i) => { if (D.quick[i]) q.name = D.quick[i]; });
  for (const f of FOODS) { const t = D.foods[f.id]; if (t) { f.n = t.n; f.a = [...f.a, ...t.a]; } }
  for (const [k, t] of Object.entries(D.levels)) if (LEVELS[k]) Object.assign(LEVELS[k], t);
